{"aggs":[],"params":{"spec":"{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "autosize": {
    "contains": "padding",
    "type": "fit"
  },
  "config": {
    "kibana": {
      "hideWarnings": true
    },
    "text": {
      "baseline": "middle",
      "fill": "#343741",
      "font": "Inter UI, -apple-system, BlinkMacSystemFont, Segoe UI, Helvetica, Arial, sans-serif",
      "fontSize": 14
    }
  },
  "data": [
    {
      "format": {
        "property": "aggregations.r.buckets"
      },
      "name": "src",
      "transform": [
        {
          "as": [
            "vb"
          ],
          "fields": [
            "v.buckets"
          ],
          "type": "flatten"
        },
        {
          "as": "rule",
          "expr": "datum.key",
          "type": "formula"
        },
        {
          "as": "value",
          "expr": "datum.vb.key",
          "type": "formula"
        },
        {
          "as": "alerts",
          "expr": "datum.vb.doc_count",
          "type": "formula"
        },
        {
          "as": "desc",
          "expr": "length(datum.d.buckets) ? datum.d.buckets[0].key : ''",
          "type": "formula"
        },
        {
          "as": "level",
          "expr": "datum.l.value",
          "type": "formula"
        }
      ],
      "url": {
        "body": {
          "aggs": {
            "r": {
              "aggs": {
                "d": {
                  "terms": {
                    "field": "rule.description",
                    "size": 1
                  }
                },
                "l": {
                  "max": {
                    "field": "rule.level"
                  }
                },
                "v": {
                  "terms": {
                    "field": "data.jt_ai.agent",
                    "missing": "-",
                    "size": 5
                  }
                }
              },
              "terms": {
                "field": "rule.id",
                "size": 50
              }
            }
          },
          "query": {
            "bool": {
              "filter": [
                "%dashboard_context-filter_clause%"
              ],
              "must": [
                "%dashboard_context-must_clause%",
                {
                  "range": {
                    "timestamp": {
                      "%timefilter%": true
                    }
                  }
                },
                {
                  "query_string": {
                    "analyze_wildcard": true,
                    "query": "rule.id:[133700 TO 133799] AND rule.id:/[0-9]{6}/"
                  }
                }
              ],
              "must_not": [
                "%dashboard_context-must_not_clause%"
              ]
            }
          },
          "size": 0
        },
        "index": "wazuh-alerts-*"
      }
    },
    {
      "name": "rows",
      "source": "src",
      "transform": [
        {
          "as": [
            "row0"
          ],
          "ops": [
            "row_number"
          ],
          "sort": {
            "field": {
              "signal": "sortField"
            },
            "order": {
              "signal": "sortDesc ? 'descending' : 'ascending'"
            }
          },
          "type": "window"
        },
        {
          "as": "row",
          "expr": "datum.row0 - 1",
          "type": "formula"
        },
        {
          "expr": "datum.row < floor((height - 38) / 34)",
          "type": "filter"
        }
      ]
    },
    {
      "name": "head",
      "values": [
        {
          "align": "left",
          "key": "rule",
          "label": "規則",
          "num": false,
          "right": false,
          "x": 0
        },
        {
          "align": "right",
          "key": "level",
          "label": "等級",
          "num": true,
          "right": false,
          "x": 135
        },
        {
          "align": "left",
          "key": "value",
          "label": "AI 代理",
          "num": false,
          "right": false,
          "x": 160
        },
        {
          "align": "right",
          "key": "alerts",
          "label": "告警",
          "num": true,
          "right": false,
          "x": 410
        },
        {
          "align": "left",
          "key": "desc",
          "label": "說明",
          "num": false,
          "right": false,
          "x": 435
        }
      ]
    }
  ],
  "marks": [
    {
      "encode": {
        "update": {
          "align": {
            "field": "align"
          },
          "cursor": {
            "value": "pointer"
          },
          "fill": {
            "value": "#1A1C21"
          },
          "fontWeight": {
            "value": "bold"
          },
          "text": {
            "signal": "datum.label + (datum.key === sortField ? (sortDesc ? ' ▼' : ' ▲') : '')"
          },
          "tooltip": {
            "value": "點擊以排序"
          },
          "x": {
            "signal": "datum.right ? width - datum.x : datum.x"
          },
          "y": {
            "value": 19.0
          }
        }
      },
      "from": {
        "data": "head"
      },
      "name": "jtHead",
      "type": "text"
    },
    {
      "encode": {
        "update": {
          "stroke": {
            "value": "#343741"
          },
          "strokeWidth": {
            "value": 2
          },
          "x": {
            "value": 0
          },
          "x2": {
            "signal": "width"
          },
          "y": {
            "value": 38
          },
          "y2": {
            "value": 38
          }
        }
      },
      "type": "rule"
    },
    {
      "encode": {
        "hover": {
          "fill": {
            "value": "#F5F7FA"
          },
          "fillOpacity": {
            "value": 1
          }
        },
        "update": {
          "fill": {
            "value": "#FFFFFF"
          },
          "fillOpacity": {
            "value": 0
          },
          "height": {
            "value": 34
          },
          "x": {
            "value": 0
          },
          "x2": {
            "signal": "width"
          },
          "y": {
            "signal": "datum.row * 34 + 38"
          }
        }
      },
      "from": {
        "data": "rows"
      },
      "type": "rect"
    },
    {
      "encode": {
        "update": {
          "stroke": {
            "value": "#D3DAE6"
          },
          "x": {
            "value": 0
          },
          "x2": {
            "signal": "width"
          },
          "y": {
            "signal": "(datum.row + 1) * 34 + 38"
          },
          "y2": {
            "signal": "(datum.row + 1) * 34 + 38"
          }
        }
      },
      "from": {
        "data": "rows"
      },
      "type": "rule"
    },
    {
      "encode": {
        "update": {
          "align": {
            "value": "left"
          },
          "cursor": {
            "value": "pointer"
          },
          "fill": {
            "value": "#006BB4"
          },
          "text": {
            "field": "rule"
          },
          "tooltip": {
            "signal": "'點擊以篩選' + ': ' + datum.rule"
          },
          "x": {
            "value": 0
          },
          "y": {
            "signal": "(datum.row + 0.5) * 34 + 38"
          }
        }
      },
      "from": {
        "data": "rows"
      },
      "name": "jtCell_rule",
      "type": "text"
    },
    {
      "encode": {
        "update": {
          "align": {
            "value": "right"
          },
          "fill": {
            "signal": "datum.level >= 12 ? '#BD271E' : '#343741'"
          },
          "text": {
            "field": "level"
          },
          "x": {
            "value": 135
          },
          "y": {
            "signal": "(datum.row + 0.5) * 34 + 38"
          }
        }
      },
      "from": {
        "data": "rows"
      },
      "type": "text"
    },
    {
      "encode": {
        "update": {
          "align": {
            "value": "left"
          },
          "cursor": {
            "value": "pointer"
          },
          "fill": {
            "value": "#006BB4"
          },
          "limit": {
            "value": 170
          },
          "text": {
            "field": "value"
          },
          "tooltip": {
            "signal": "'點擊以篩選' + ': ' + datum.value"
          },
          "x": {
            "value": 160
          },
          "y": {
            "signal": "(datum.row + 0.5) * 34 + 38"
          }
        }
      },
      "from": {
        "data": "rows"
      },
      "name": "jtCell_value",
      "type": "text"
    },
    {
      "encode": {
        "update": {
          "align": {
            "value": "right"
          },
          "text": {
            "signal": "format(datum.alerts, ',')"
          },
          "x": {
            "value": 410
          },
          "y": {
            "signal": "(datum.row + 0.5) * 34 + 38"
          }
        }
      },
      "from": {
        "data": "rows"
      },
      "type": "text"
    },
    {
      "encode": {
        "update": {
          "align": {
            "value": "left"
          },
          "limit": {
            "signal": "width - 435"
          },
          "text": {
            "field": "desc"
          },
          "tooltip": {
            "field": "desc"
          },
          "x": {
            "value": 435
          },
          "y": {
            "signal": "(datum.row + 0.5) * 34 + 38"
          }
        }
      },
      "from": {
        "data": "rows"
      },
      "type": "text"
    }
  ],
  "padding": {
    "bottom": 4,
    "left": 8,
    "right": 8,
    "top": 4
  },
  "signals": [
    {
      "name": "sortBy",
      "on": [
        {
          "events": "@jtHead:click",
          "update": "{field: datum.key, desc: datum.key === sortBy.field ? !sortBy.desc : datum.num}"
        }
      ],
      "value": {
        "desc": true,
        "field": "alerts"
      }
    },
    {
      "name": "sortField",
      "update": "sortBy.field"
    },
    {
      "name": "sortDesc",
      "update": "sortBy.desc"
    },
    {
      "name": "jtCell_ruleFilter",
      "on": [
        {
          "events": "@jtCell_rule:click",
          "update": "datum.rule === '-' ? null : opensearchDashboardsAddFilter({'match_phrase': {\"rule.id\": datum.rule}}, \"wazuh-alerts-*\", \"rule.id\" + ': ' + datum.rule)"
        }
      ],
      "value": null
    },
    {
      "name": "jtCell_valueFilter",
      "on": [
        {
